mapper.select:
SELECT a.id AS "id", a.name AS "name", o.office_name AS "organization", p.position_name AS "workshop", fpl.prod_line_name AS "process", wg.work_group_name AS "team", NULL AS "deviceId", NULL AS "workStatus", NULL AS "helmetStatus", a.personnel_status AS "personnelStatus", 0 AS "attendanceCount", 0 AS "workingHours", 0 AS "idleHours", a.identity_card AS "idCard", a.create_by AS "createBy", a.create_date AS "createDate", a.update_by AS "updateBy", a.update_date AS "updateDate", a.remarks AS "remarks", a.status AS "status" FROM swm_person a LEFT JOIN fms_worker f ON a.identity_card = f.identity_code COLLATE utf8mb4_general_ci LEFT JOIN js_sys_office o ON f.office_code = o.office_code AND o.zip_code IS NOT NULL LEFT JOIN fms_position_archive p ON f.work_shop_code = p.id AND p.type = 'CJ' LEFT JOIN fms_work_group wg ON f.work_group_id = wg.id LEFT JOIN fms_prod_line fpl ON fpl.id = wg.prod_line_id
AND a.name LIKE CONCAT('%', #{name}, '%')
AND o.office_name LIKE CONCAT('%', #{organization}, '%')
AND p.position_name LIKE CONCAT('%', #{workshop}, '%')
AND fpl.prod_line_name LIKE CONCAT('%', #{process}, '%')
AND wg.work_group_name LIKE CONCAT('%', #{team}, '%')
AND a.personnel_status = #{workStatus}
AND ${sqlMap.where.toSql()}
ORDER BY ${sqlMap.order.toSql()}
